#!/usr/bin/env python3
"""Removes AI attribution footers from the repository's issues, pull requests and comments.

Some tools append "Generated by Claude Code", a session link or a co-author trailer to what
they post, and CLAUDE.md forbids them. This script edits them back out of issue and pull
request descriptions, conversation comments, review comments and review summaries.

Only whole lines in the footer's own form are removed, outside code blocks: a description
that quotes the footer in a sentence or in backticks is left as it is.

It needs the GitHub CLI (`gh`), logged in with write access to the repository.

    python3 .github/scripts/strip-ai-footers.py                 # every issue and pull request
    python3 .github/scripts/strip-ai-footers.py --dry-run       # only list what would change
    python3 .github/scripts/strip-ai-footers.py --number 93     # one issue or pull request

The `strip-ai-footers` workflow runs it on each new or edited issue, pull request or comment.
"""

import argparse
import json
import os
import re
import subprocess
import sys

FOOTER_LINES = [
    # 🤖 Generated with [Claude Code](https://claude.com/claude-code)
    # _Generated by [Claude Code](https://claude.ai/code/session_...)_
    re.compile(r"^\s*[_*]*\s*(🤖\s*)?Generated (by|with) \[Claude Code\]\([^)]*\)\s*[_*]*\s*$", re.I),
    re.compile(r"^\s*[_*]*\s*(🤖\s*)?Generated (by|with) Claude Code\.?\s*[_*]*\s*$", re.I),
    # https://claude.ai/code/session_...
    re.compile(r"^\s*<?https://claude\.ai/code/session_\S*>?\s*$"),
    re.compile(r"^\s*Claude-Session:.*$", re.I),
    re.compile(r"^\s*Co-Authored-By:.*\b(Claude|anthropic\.com)\b.*$", re.I),
]
FENCE = re.compile(r"^\s*(```|~~~)")
RULE = re.compile(r"^\s*(-{3,}|\*{3,}|_{3,})\s*$")


def strip(body):
    """The body without its footer lines, or None when it has none."""
    if not body:
        return None
    lines = body.replace("\r\n", "\n").split("\n")
    kept, removed, fenced = [], False, False
    for line in lines:
        if FENCE.match(line):
            fenced = not fenced
        if not fenced and any(p.match(line) for p in FOOTER_LINES):
            removed = True
            continue
        kept.append(line)
    if not removed:
        return None
    # The footer came after a rule and blank lines: drop what it leaves dangling at the end.
    while kept and (not kept[-1].strip() or RULE.match(kept[-1])):
        kept.pop()
    return "\n".join(kept)


def gh(*args, payload=None):
    result = subprocess.run(
        ["gh", "api", *args],
        input=json.dumps(payload) if payload is not None else None,
        capture_output=True, text=True, encoding="utf-8",
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip() or result.stdout.strip())
    return json.loads(result.stdout) if result.stdout.strip() else None


def pages(path):
    """Every item of a paginated list."""
    sep = "&" if "?" in path else "?"
    page = 1
    while True:
        items = gh(f"{path}{sep}per_page=100&page={page}")
        if not items:
            return
        yield from items
        if len(items) < 100:
            return
        page += 1


def targets(repo, number):
    """(label, method, url, body) for everything that may carry a footer."""
    base = f"repos/{repo}"
    if number is None:
        issues = list(pages(f"{base}/issues?state=all"))
        comments = pages(f"{base}/issues/comments")
        review_comments = pages(f"{base}/pulls/comments")
    else:
        issues = [gh(f"{base}/issues/{number}")]
        comments = pages(f"{base}/issues/{number}/comments")
        is_pull = "pull_request" in issues[0]
        review_comments = pages(f"{base}/pulls/{number}/comments") if is_pull else []

    for issue in issues:
        kind = "pull request" if "pull_request" in issue else "issue"
        yield f"{kind} #{issue['number']}", "PATCH", f"{base}/issues/{issue['number']}", issue.get("body")
    for c in comments:
        yield f"comment {c['html_url']}", "PATCH", f"{base}/issues/comments/{c['id']}", c.get("body")
    for c in review_comments:
        yield f"review comment {c['html_url']}", "PATCH", f"{base}/pulls/comments/{c['id']}", c.get("body")
    for issue in issues:
        if "pull_request" not in issue:
            continue
        n = issue["number"]
        for r in pages(f"{base}/pulls/{n}/reviews"):
            yield f"review {r['html_url']}", "PUT", f"{base}/pulls/{n}/reviews/{r['id']}", r.get("body")


def default_repo():
    if os.environ.get("GITHUB_REPOSITORY"):
        return os.environ["GITHUB_REPOSITORY"]
    result = subprocess.run(["gh", "repo", "view", "--json", "nameWithOwner", "-q", ".nameWithOwner"],
                            capture_output=True, text=True)
    return result.stdout.strip() or "MC-Skin-Creator/living-horizon"


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--repo", default=None, help="owner/name, by default this repository")
    parser.add_argument("--number", type=int, help="only this issue or pull request")
    parser.add_argument("--dry-run", action="store_true", help="list what would change, edit nothing")
    args = parser.parse_args()
    repo = args.repo or default_repo()

    changed = failed = 0
    for label, method, url, body in targets(repo, args.number):
        new = strip(body)
        if new is None:
            continue
        changed += 1
        if args.dry_run:
            print(f"would clean {label}")
            continue
        try:
            gh("-X", method, url, "--input", "-", payload={"body": new})
            print(f"cleaned {label}")
        except RuntimeError as e:
            failed += 1
            print(f"could not clean {label}: {e}", file=sys.stderr)

    verb = "to clean" if args.dry_run else "cleaned"
    print(f"{changed - failed} {verb}, {failed} failed, in {repo}")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
